mapper.select:
SELECT COUNT(*)
FROM retention_intervention
WHERE user_id = #{userId}
  AND risk_type = #{riskType}
  AND action_type = #{actionType}
  AND created_at > NOW() - CAST(#{days} || ' days' AS INTERVAL)

SELECT COALESCE(
    (SELECT is_control FROM retention_intervention
      WHERE user_id = #{userId}
        AND risk_type = #{riskType}
        AND action_type = #{actionType}
      ORDER BY created_at DESC
      LIMIT 1), FALSE)
